package rules

import (
	"testing"

	"blink/internal/fixer"
)

// TestSingleSpaceAroundConstructMatchesPHPCSFixer runs the registry's rule
// (PHP-CS-Fixer's default construct lists) over every kind of construct,
// virtual ones included; the expected outputs come from PHP-CS-Fixer.
func TestSingleSpaceAroundConstructMatchesPHPCSFixer(t *testing.T) {
	t.Parallel()
	cases := []struct{ in, want string }{
		{"<?php  \nnamespace  Foo;\nuse  Bar\\Baz;\nuse   function Bar\\f;\nuse const  Bar\\C;\nuse Bar\\{const  D, function  g};\nabstract  class  A  extends  B  implements  C,\n    D\n{\n    use  T;\n    const  X = 1, Y = 2;\n    const Z = [\n        1,\n    ], W = 3;\n    public  static  function  m():int { return  1; }\n    protected  $p;\n    var  $v;\n    private  readonly  int $r;\n    final public function n()\n    {\n        static  $s;\n        $c = clone  $this;\n        $f = function()use($c) { return$c; };\n        $g = static  fn() => 1;\n        $h = new  class( $a ) {};\n        $i = new  Foo;\n        $j = $c instanceof  A;\n        if($a){}elseif($b){}else{}\n        while($a){}\n        do{}while(0);\n        for(;;){}\n        foreach($a as  $b){}\n        switch($a){case  1: break;default: break 2;}\n        try{}catch(E $e){}finally{}\n        throw  new E();\n        echo  1; print  2;\n        include  'a.php'; require_once('b.php');\n        goto  end;\n        yield  $x;\n        yield  from  g();\n        yield\n            from h();\n        global  $gl;\n        $m = match($a) { default => 1 };\n        foo(a:1, b:  2);\n        return\n            $x;\n        return [\n            1,\n        ];\n        return\n            1;\n    }\n}\ninterface I extends J,\n    K {}\ntrait T { use U { a as  protected b; X::c insteadof  Y; } }\nenum E: string { case  A = 'a'; }\n/* c */$x = 1;\n/** @var int */  $y = 1;\n#[Attr]  function k() {}\n$z = static::$a;\n$q = new static;\nfunction &r() {}\necho $a?>\n<?=  $b ?>\n<?php\nif ($a) {\n}\nelse {\n}\n", "<?php  \nnamespace Foo;\nuse Bar\\Baz;\nuse function Bar\\f;\nuse const Bar\\C;\nuse Bar\\{const D, function g};\nabstract class A  extends  B  implements  C,\n    D\n{\n    use T;\n    const X = 1, Y = 2;\n    const Z = [\n        1,\n    ], W = 3;\n    public static function m(): int { return 1; }\n    protected $p;\n    var $v;\n    private readonly int $r;\n    final public function n()\n    {\n        static $s;\n        $c = clone $this;\n        $f = function () use ($c) { return $c; };\n        $g = static fn() => 1;\n        $h = new class( $a ) {};\n        $i = new Foo;\n        $j = $c instanceof A;\n        if ($a){}elseif ($b){}else {}\n        while ($a){}\n        do {}while (0);\n        for (;;){}\n        foreach ($a as $b){}\n        switch ($a){case 1: break;default: break 2;}\n        try {}catch (E $e){}finally {}\n        throw new E();\n        echo 1; print 2;\n        include 'a.php'; require_once ('b.php');\n        goto end;\n        yield $x;\n        yield from g();\n        yield from h();\n        global $gl;\n        $m = match ($a) { default => 1 };\n        foo(a: 1, b: 2);\n        return $x;\n        return [\n            1,\n        ];\n        return 1;\n    }\n}\ninterface I extends J,\n    K {}\ntrait T { use U { a as protected b; X::c insteadof Y; } }\nenum E: string { case A = 'a'; }\n/* c */ $x = 1;\n/** @var int */ $y = 1;\n#[Attr] function k() {}\n$z = static::$a;\n$q = new static;\nfunction &r() {}\necho $a?>\n<?= $b ?>\n<?php\nif ($a) {\n}\nelse {\n}\n"},
		{"<?php   $a = 1;\n$r = new static ($x);\n$s = new Enum ($type);\n$t = namespace\\foo();\nif ($a) {\n}\n// note\nelse {\n}\nif ($a) {\n}\n/* c */\nelseif ($b) {\n}\nif ($a) {\n}else{\n}\nforeach ($a   as $b) {}\n$f = function () use ($c) {};\n$f2 = function ()use ($c) {};\n$f3 = function ()\n    use ($c) {};\nclass Q {\n    public function __construct(\n        public  int $a,\n        protected\n            int $b,\n    ) {}\n    #[A]\n    public function x() {}\n    /** doc */\n    public\n    /** doc */\n    function y() {}\n}\n$x = $y->class;\n$z = Foo::new;\nf(class: 1);\necho\n    'x';\nreturn;\n", "<?php $a = 1;\n$r = new static ($x);\n$s = new Enum ($type);\n$t = namespace\\foo();\nif ($a) {\n}\n// note\nelse {\n}\nif ($a) {\n}\n/* c */\nelseif ($b) {\n}\nif ($a) {\n}else {\n}\nforeach ($a as $b) {}\n$f = function () use ($c) {};\n$f2 = function () use ($c) {};\n$f3 = function () use ($c) {};\nclass Q {\n    public function __construct(\n        public int $a,\n        protected int $b,\n    ) {}\n    #[A]\n    public function x() {}\n    /** doc */\n    public\n    /** doc */\n    function y() {}\n}\n$x = $y->class;\n$z = Foo::new;\nf(class: 1);\necho 'x';\nreturn;\n"},
		{"<?php\nclass A {\n    public function clone(): self {}\n    public static function new(): self {}\n    public function list(): array {}\n    public function &print(): array {}\n    const NEW = 1;\n    const PRINT= 2;\n    public function __construct(public private(set) int $a, protected(set)  ?int $b = null) {}\n}\nenum E { case NEW; case Print; }\n$x = A::new();\n$y = A::NEW;\n$z = new A(print: 1);\n", "<?php\nclass A {\n    public function clone(): self {}\n    public static function new(): self {}\n    public function list(): array {}\n    public function &print(): array {}\n    const NEW = 1;\n    const PRINT= 2;\n    public function __construct(public private(set) int $a, protected(set) ?int $b = null) {}\n}\nenum E { case NEW; case Print; }\n$x = A::new();\n$y = A::NEW;\n$z = new A(print: 1);\n"},
	}
	var f fixer.Fixer
	f, _ = ByName(`PhpCsFixer\Fixer\LanguageConstruct\SingleSpaceAroundConstructFixer`)
	for i, c := range cases {
		if got, _ := apply(t, f, c.in); got != c.want {
			t.Errorf("case %d:\n got %q\nwant %q", i, got, c.want)
		}
	}
}
